'use strict';
const $=s=>document.querySelector(s), offline=Array.isArray(window.SAVED_EVOLUTION);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,n=4)=>typeof x==='number'&&Number.isFinite(x)?x.toFixed(n):'—';
const pct=x=>typeof x==='number'&&Number.isFinite(x)?(100*x).toFixed(1)+'%':'—';
const families={reversal:'反转',trend:'趋势',activity:'成交活动',risk:'风险',price_volume:'价量交互',price_location:'价格位置',hybrid:'跨家族组合'};
const statuses={ready:'可继续研究',running:'运行中',interrupted:'等待继续',frozen:'已冻结'};
let studies=[],current=null,busy=false,timer=null;
async function api(path,payload){const r=await fetch(path,payload===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||'请求失败');return data}
function error(e){$('#error').textContent=e?.message||String(e)}
function guarded(fn){return async e=>{try{$('#error').textContent='';await fn(e)}catch(e){error(e)}}}
async function list(){studies=offline?window.SAVED_EVOLUTION:await api('/api/evolution');$('#studies').innerHTML=studies.length?studies.map(s=>`<button class="study-link ${current?.id===s.id?'selected':''}" data-study="${esc(s.id)}"><strong>${esc(s.config.name)}</strong><small>${esc(s.created_at.slice(0,10))} · ${s.rounds_completed}/${s.config.round_budget}轮 · ${esc(statuses[s.status]||s.status)}</small></button>`).join(''):'<p class="muted">尚无实验。创建研究后，记录会保存在这里。</p>';document.querySelectorAll('[data-study]').forEach(b=>b.onclick=guarded(()=>load(b.dataset.study)))}
async function load(id){clearTimeout(timer);current=offline?studies.find(s=>s.id===id):await api('/api/evolution/'+id);busy=current.status==='running';$('#new-study').hidden=true;$('#study-content').hidden=false;render();await list();if(busy&&!offline)timer=setTimeout(()=>load(id).catch(error),2500)}
function render(){const s=current,c=s.config,rows=Object.values(s.candidates),accepted=rows.filter(r=>r.accepted&&r.round>0).length;$('#study-name').textContent=c.name;$('#study-meta').textContent=`${c.harness} / ${s.id}`;$('#study-state').textContent=s.status==='ready'&&s.rounds_completed>=c.round_budget?'预算已完成，待冻结':statuses[s.status]||s.status;$('#scope').textContent=`${c.pool==='liquid'?'流动性池：20日均成交额≥2000万，股价≥3元':'历史非ST基础池'}　·　未来${c.horizon}日　·　搜索 ${c.search_start}—${c.search_end}　·　选择验证 ${c.validation_start}—${c.validation_end}`;$('#stage').textContent=s.stage+(s.error?'：'+s.error:'');
const baseline=s.baseline?.metrics?.validation?.rank_ic,latest=s.pool_metrics?.validation?.rank_ic;
$('#stats').innerHTML=[['研究进度',`${s.rounds_completed} / ${c.round_budget}`,'每轮最多3个新候选'],['新候选保留',`${accepted} / ${rows.filter(r=>r.round>0).length}`,'全部失败结果一并保存'],['当前组合验证IC',num(latest),'等权排名组合'],['相对初始组合',latest!=null&&baseline!=null?num(latest-baseline):'—','选择验证段 · 不代表净收益']].map(x=>`<div class="stat"><label>${x[0]}</label><b>${x[1]}</b><small>${x[2]}</small></div>`).join('');
$('#run').textContent=!rows.length?'评价5个起始因子':s.pending?'继续未完成批次':'运行下一轮规则候选';$('#run').disabled=busy||!!s.frozen||(!s.pending&&rows.length>0&&s.rounds_completed>=c.round_budget);$('#freeze').disabled=busy||!!s.frozen||!!s.pending||!s.baseline;$('#review').disabled=busy||!s.frozen||!!s.review;$('#suggest').disabled=busy||!!s.frozen||!!s.pending||!rows.length||s.rounds_completed>=c.round_budget;$('#run-import').disabled=$('#suggest').disabled;
$('#factor-pool').innerHTML=s.pool.length?'<div class="pool-grid">'+s.pool.map(k=>{const r=s.candidates[k];return `<div class="factor"><small>${esc(families[r.spec.family]||r.spec.family)}</small><b>${esc(k)}</b><code>${esc(r.spec.formula)}</code><small>验证IC ${num(r.metrics.validation.rank_ic)} · 第${r.round}轮保留</small></div>`}).join('')+'</div>':'<p class="muted">尚无通过全部门槛的因子；不会自动填入未通过的候选。</p>';
const selected=$('#round-filter').value;$('#round-filter').innerHTML='<option value="all">全部轮次</option>'+[...new Set(rows.map(r=>r.round))].map(n=>`<option value="${n}">${n===0?'初始因子':'第'+n+'轮'}</option>`).join('');if([...$('#round-filter').options].some(o=>o.value===selected))$('#round-filter').value=selected;renderCandidates();
$('#timeline').innerHTML=s.rounds.length?s.rounds.map(r=>`<div class="step"><b>${r.round===0?'初始因子评价':'第 '+r.round+' 轮'} · ${esc(r.harness)} · ${r.source==='agent-import'?'Agent导入':r.source==='seed'?'已有因子':'规则基线'}</b><p>${esc(r.specs.map(x=>x.key).join(' → '))}</p><p>保留池：${esc(r.pool.join('、')||'空')} · 组合验证IC ${num(r.pool_metrics?.validation?.rank_ic)}</p><details><summary>查看本轮输入与反馈</summary><pre>${esc(r.feedback)}</pre></details></div>`).join(''):'<p class="muted">运行初始评价后，研究过程将显示在这里。</p>';
$('#review-results').innerHTML=s.review?'<div class="review-grid">'+Object.entries(s.review).map(([k,v])=>`<div class="review-item"><h3>${esc({seed_pool:'初始因子池',selected_pool:'冻结因子池',reversal5:'5DR基准'}[k]||k)}</h3><b>${num(v.metrics?.rank_ic)}</b><p>回顾Rank IC · 正IC月份 ${pct(v.metrics?.positive_months)}</p><p>成员 ${esc(v.members.join('、')||'无合格成员')}</p><p>Q5−Q1报价收益 ${v.metrics?.spread==null?'—':(v.metrics.spread*100).toFixed(3)+'%'}</p></div>`).join('')+'</div><p class="muted">2026历史此前已查看；此处为冻结后回顾。分组报价未扣费，未完成新组合的净交易账户验证。</p>':'<p class="muted">选型冻结后才运行2026检查。已有历史不能重新称为未见样本；检查结果不会回写选型。</p>';
$('#protocol').innerHTML=`<p>${esc(c.policy.note)}</p><p>${esc(c.review_note)}</p><p>${esc(s.generation)}</p><p>参数指纹：${esc(s.config_hash)}</p><p>数据指纹：${esc(s.provenance?.data_sha256||'首次运行时生成')}</p><p>数据列数：${esc(s.provenance?.securities||'待加载')}；因子方向预先固定；每个候选执行截断未来数据的因果性核对。</p>`;
if(offline){$('#proposal-section').hidden=true;document.querySelectorAll('#actions button:not(#export)').forEach(b=>b.hidden=true)}}
function renderCandidates(){if(!current)return;const filter=$('#round-filter').value,rows=Object.values(current.candidates).filter(r=>filter==='all'||String(r.round)===filter);$('#candidates').innerHTML=rows.length?rows.map(r=>{const correlations=Object.values(r.correlations).filter(x=>typeof x==='number'),m=r.metrics;return `<tr><td><small>${r.round===0?'初始':'第'+r.round+'轮'} · ${esc(families[r.spec.family]||r.spec.family)}</small><details><summary>${esc(r.spec.key)}</summary><p><code>${esc(r.spec.formula)}</code></p><p>父因子：${esc(r.spec.parent||'新方向')}</p><p>假设：${esc(r.spec.hypothesis)}</p><p>决定：${esc(r.reasons.join('；'))}</p><p>覆盖率：搜索 ${pct(m.search.coverage)} / 验证 ${pct(m.validation.coverage)}</p><p>因果性核对：${r.prefix_check?'通过':'未完成'}</p></details></td><td>${num(m.search.rank_ic)}</td><td>${num(m.validation.rank_ic)}</td><td>${pct(m.validation.positive_months)}</td><td>${correlations.length?num(Math.max(...correlations),3):'—'}</td><td>${num(r.pool_validation_gain)}</td><td class="${r.accepted?'accepted':'rejected'}">${r.accepted?'当轮保留':'淘汰'}</td></tr>`}).join(''):'<tr><td colspan="7">尚无已完成的候选评价。</td></tr>'}
async function action(payload){busy=true;render();const id=current.id;try{const response=await api('/api/evolution/'+id,payload);if(!response.job_id){await load(id);return}$('#stage').textContent='研究已进入队列；关闭页面后任务仍会继续。';const poll=async()=>{try{const job=await api('/api/jobs/'+response.job_id);current=await api('/api/evolution/'+id);busy=['queued','running'].includes(job.status);render();$('#stage').textContent=job.stage+(job.error?'：'+job.error:'');if(busy)timer=setTimeout(poll,2000);else{await list();if(job.error)error(job.error)}}catch(e){busy=false;render();error(e)}};timer=setTimeout(poll,500)}catch(e){busy=false;render();throw e}}
$('#create-form').onsubmit=guarded(async e=>{e.preventDefault();const submit=e.target.querySelector('[type=submit]');submit.disabled=true;try{const s=await api('/api/evolution',{name:$('#name').value,pool:$('#pool').value,harness:$('#harness').value,horizon:Number($('#horizon').value),round_budget:Number($('#budget').value),search_start:$('#search-start').value,search_end:$('#search-end').value,validation_start:$('#validation-start').value,validation_end:$('#validation-end').value});await load(s.id)}finally{submit.disabled=false}});
$('#new-button').onclick=()=>{$('#new-study').hidden=false;$('#new-study').scrollIntoView({behavior:'smooth',block:'start'})};
$('#run').onclick=guarded(()=>action({action:'run'}));$('#freeze').onclick=guarded(()=>action({action:'freeze'}));$('#review').onclick=guarded(()=>action({action:'review'}));$('#round-filter').onchange=renderCandidates;
$('#suggest').onclick=guarded(async()=>{const p=await api('/api/evolution/'+current.id+'/proposal');$('#proposals').value=JSON.stringify(p.candidates,null,2);$('#feedback').textContent=p.feedback;$('#proposal-note').value='';});
$('#run-import').onclick=guarded(async()=>{const candidates=JSON.parse($('#proposals').value);if(!Array.isArray(candidates)||!candidates.length)throw new Error('请先准备候选JSON数组');await action({action:'run',candidates,feedback:$('#proposal-note').value||'用户编辑并提交的结构化候选'})});
$('#export').onclick=()=>{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify(current,null,2)],{type:'application/json'}));a.href=url;a.download='stoneflow-evolution-'+current.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
(async()=>{try{if(offline){$('#mode').textContent='已保存的研究快照';$('#new-button').hidden=true;$('#new-study').hidden=true;document.querySelectorAll('a[href="/"]').forEach(a=>a.href='index.html');document.querySelectorAll('a[href="/factors"]').forEach(a=>a.href='factors.html');document.querySelectorAll('a[href="/factors/improve"]').forEach(a=>a.href='evolution.html');document.querySelectorAll('a[href^="/reports/"]').forEach(a=>a.href=a.getAttribute('href').replace('/reports/',''));}await list();if(studies.length)await load(studies[0].id)}catch(e){error(e)}})();
